INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(124158, 'ruRU', '', 'Благодарю Элуну, что ты здесь! Мне не помешала бы помощь с этим.', 24330),
(124159, 'ruRU', '', 'Сюда! Я чувствую, как энергии сходятся внизу, но агрессивные стражи преграждают мой путь. Мне нужно, чтобы ты расчистил дорогу.', 24330),
(124162, 'ruRU', '', 'Благодарю, Сильгрин. Будь осторожен.', 24330),
(124163, 'ruRU', '', 'Мне нужно будет сохранять концентрацию, чтобы это сработало... ты готов помочь мне в этом деле?', 24330),
(124164, 'ruRU', '', 'Говори тише, Сильгрин. Я тоже рад тебя видеть.', 24330),
(124167, 'ruRU', '', 'Такой, что найдёт нашего друга.', 24330),
(124170, 'ruRU', '', 'Как пожелаешь, Военачальник. Готов отправляться?', 24330),
(124173, 'ruRU', '', 'Весьма эффективно! Давай взглянем поближе... Скажу, это впечатляющая работа с заклинаниями.', 24330),
(124176, 'ruRU', '', 'Возможно, скважина маны? Хм... ничего. Это требует огромной силы для поддержания.', 24330),
(124178, 'ruRU', '', 'Это не подключено к Ночному Колодцу, а к лей-линиям. Но мы их контролируем, так как же она могла... Ах, да. Понимаю!', 24330),
(124200, 'ruRU', '', 'Небеса темнеют. Нам нужно продвигаться дальше.', 24330),
(124209, 'ruRU', '', 'Я не покину этот остров, пока каждый демон не будет убит, а каждый павший воин Орды не будет отмщён!', 24330),
(124234, 'ruRU', '', 'Прекрасно, мой любимый сыр.', 24330),
(124254, 'ruRU', '', 'Я... я в порядке. Что произошло?', 24330),
(124256, 'ruRU', '', 'Во время раскола Азерота было потеряно много знаний. Но я, Лунелли, говорю с землёй и ветром.$b$bОни рассказали мне многое и дали знания, чтобы передать тем, кто считает себя достойным.$b$bТак что, ты один из таких?', 24330),
(124259, 'ruRU', '', 'Я не успел поднять свой щит вовремя. Что случилось?', 24330),
(124292, 'ruRU', '', 'Подожди... что ты—', 24330),
(124293, 'ruRU', '', 'Используй Духов волка прямо сейчас, чтобы призвать этих духов.', 24330),
(124295, 'ruRU', '', 'Легион пытался использовать своих агентов, чтобы подорвать наши усилия у Гробницы Саргераса. Благодаря твоим усилиям, они провалились.', 24330),
(124296, 'ruRU', '', 'Теперь мы сосредоточимся на том, чтобы изгнать их армии из Азерота. Мы отдадим всё, что у нас есть, и закончим это... раз и навсегда!', 24330),
(124298, 'ruRU', '', 'Вместе! Мы все должны отдать свою силу!', 24330),
(124299, 'ruRU', '', 'Отойди и поднимай своё оружие. Мы наделим его частью силы этого совета.', 24330),
(124301, 'ruRU', '', 'Ты пытался спрятаться, Иссохший? Я смогла почувствовать следы твоей телепортации из Лазурного Крыла!', 24330),
(124302, 'ruRU', '', 'Лишь присутствие нашего защитника удерживает мою руку. Говори быстро.', 24330),
(124303, 'ruRU', '', 'Расположив отводы в ключевых точках лей-линии, я могу направлять её поток.', 24330),
(124304, 'ruRU', '', 'Ты уверен насчёт этого расположения? Лучше было бы здесь.', 24330),
(124305, 'ruRU', '', 'Но я вижу линию и фокус канала. Ты хочешь поставить его там.', 24330),
(124306, 'ruRU', '', 'Ты можешь это сделать? Возможно, ты всё-таки кое-что понимаешь.', 24330),
(124307, 'ruRU', '', 'Подожди! Это не то, на что похоже! Нам просто нужно подключиться к... Ох. Похоже, это именно то, на что похоже...', 24330),
(124308, 'ruRU', '', 'Я не "тыкаю" в неё, я подключаюсь— Хмф. Полагаю, там могло бы сработать...', 24330),
(124309, 'ruRU', '', 'Я провёл тысячелетия, изучая лей-линии. Я уж точно способен найти одну прямо у себя под ногами!', 24330),
(124310, 'ruRU', '', 'Хорошо! Сделаем по-твоему. Но если вся эта пещера взорвётся тайной энергией, это будет на твоей совести.', 24330),
(124311, 'ruRU', '', 'Этот последний отвод позволит мне направлять поток энергии, как руль корабля. Прямо здесь должно сработать.', 24330),
(124312, 'ruRU', '', 'Боже мой. Это был комплимент?', 24330),
(124320, 'ruRU', '', 'Ритуал требует моей полной концентрации. Прошу, проследи, чтобы меня не прерывали.', 24330),
(124321, 'ruRU', '', 'Потоки хаотичны... это займёт время.', 24330),
(124322, 'ruRU', '', 'Почти... готово. Нужно лишь продержаться ещё немного!', 24330),
(124323, 'ruRU', '', 'Готово! Поток был перенаправлен в Шал''Аран.', 24330),
(124324, 'ruRU', '', 'Ты сделал достаточно, чародей. Я отведу вас обоих в Шал''Аран. Идём со мной.', 24330),
(124328, 'ruRU', '', 'Если собираешься тыкать в лей-линию, хотя бы убедись, что это правильное место. Попробуй немного правее.', 24330);
